const lockUserCoupon = `-- name: LockUserCoupon :execrows

UPDATE user_coupons
   SET status = 2, order_id = $1, locked_at = now()
 WHERE id = $2
   AND user_id = $3
   AND status = 1
   AND valid_start_at <= now()
   AND valid_end_at > now()
`

type LockUserCouponParams struct {
	OrderID *int64
	ID      int64
	UserID  int64
}

// ---------------------------------------------------------------------------
// SAGA 券分支与它的两个下游（支付回调、超时关单）。数据模型 §7 的状态机。
// ---------------------------------------------------------------------------
// 券分支正向：1 未使用 → 2 锁定，回填 order_id。**返回 1 才算锁上。**
//
// 条件更新，与扣库存同构：抢不到说明已被别的单占用 / 已用掉 / 已过期 / 不是这个
// 买家的，四种都是「这张券本单用不了」，SAGA 据此失败并补偿掉前面的建单分支。
// 有效期在这里用数据库的 now() 判：这是最终的判定点，试算时判过的只是预告。
// uk_user_coupons_order 在背后兜着「一单至多一张券」。
func (q *Queries) LockUserCoupon(ctx context.Context, arg LockUserCouponParams) (int64, error) {
	result, err := q.db.Exec(ctx, lockUserCoupon, arg.OrderID, arg.ID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const unlockCouponForOrder = `-- name: UnlockCouponForOrder :execrows
UPDATE user_coupons
   SET status = 1, order_id = NULL, locked_at = NULL
 WHERE order_id = $1 AND status = 2
`

// 2 锁定 → 1 未使用。SAGA 券分支的补偿与超时关单共用。
//
// 按 order_id 找，不按券 id：两个调用方手里都只有订单，而「这张券现在被哪一单占着」
// 正是 order_id 这一列的语义。status = 2 在谓词里 —— 一张已经被付掉（3）的券
// 不该被一次迟到的补偿退回去，那时受影响 0 行，由调用方决定要不要出声。
func (q *Queries) UnlockCouponForOrder(ctx context.Context, orderID *int64) (int64, error) {
	result, err := q.db.Exec(ctx, unlockCouponForOrder, orderID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
